INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1016, '数学', '三年级', '应用题', 2, '{"stem": "一枝百合花6元，小亚的妈妈买了14枝，一共要付多少元？（1）把竖式填完整：先算 6×（ ）=24，再算 6×（ ）=60，最后 24+60=84。答：一共要付（ ）元。（2）上面竖式中圈出的这一步（60），表示买（ ）枝百合花要付的钱。", "options": null}', '84元；买10枝要付60元', '竖式14×6：个位 6×4=24（4×6=24），十位 6×10=60，24+60=84。圈出的60 表示买10枝要付的钱（10×6=60）。', 'paper', '["practice", "VG-G3-2-3", "ykl3sx", "2.3"]', NULL, 0);

