INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1016, '数学', '三年级', '选择', 2, '{"stem": "16×4 的竖式算理与（ ）是相同的。A. 16×4=16×2×2  B. 16×4=8×4+8×4  C. 16×4=4×6+4×10  D. 16×4=20×4−4×4", "options": null}', 'C', '竖式16×4：先算个位 4×6=24，再算十位 4×10=40，最后 24+40=64，对应 C（4×6+4×10）。', 'paper', '["practice", "VG-G3-2-3", "ykl3sx", "2.3"]', NULL, 0);

