INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1016, '数学', '三年级', '拓展', 3, '{"stem": "竖式谜：□□ × 4 = 9□ ，你能写出所有可能吗？", "options": null}', '23×4=92；24×4=96', '设十位为a、个位为b：a×4+进位=9（十位），b×4 进位=1（因为十位需+1才得9）。b×4≥10 且<20 → b=3 或 4 → 23×4=92，24×4=96。', 'paper', '["practice", "VG-G3-2-3", "ykl3sx", "2.3"]', NULL, 0);
